"""Build a bounded editorial collection with distinct buying and operational intents."""
from pathlib import Path
import json, html, xml.etree.ElementTree as ET
R=Path(__file__).resolve().parents[2]
BASE='https://www.arquindex.com.br/'
pages=[]
def add(slug,title,desc,lead,sections):
 pages.append(dict(path=slug+'/index.html',url=BASE+slug+'/',title=title,description=desc,lead=lead,sections=sections))
add('gestao-documental-brasil','Gestão documental no Brasil: digitalização, ECM e LGPD | Arquindex','Conheça os critérios para integrar digitalização, Alfresco ECM, LGPD e guarda digital. Atendimento com foco na RM BH e RM SP.',
 'Transformar papel em informação útil exige uma cadeia de trabalho: classificar, capturar, conferir, localizar, controlar o acesso e preservar. A Arquindex reúne digitalização, organização documental, Alfresco ECM, consultoria LGPD e guarda digital em projetos definidos pelo uso real dos documentos.',[
 ('Qual serviço resolve cada necessidade?', '<div class="table"><table><tr><th>Necessidade</th><th>Primeiro passo</th><th>Entrega a verificar</th></tr><tr><td>Encontrar documentos em papel</td><td>Inventário e classificação</td><td>Localização por caixa, pasta e tipo</td></tr><tr><td>Pesquisar arquivos escaneados</td><td>Digitalização com OCR</td><td>Imagem legível e texto pesquisável</td></tr><tr><td>Controlar versões e acessos</td><td>Projeto de ECM</td><td>Permissões, metadados e histórico</td></tr><tr><td>Organizar dados pessoais</td><td>Diagnóstico LGPD</td><td>Mapa de dados e plano de ação</td></tr><tr><td>Preservar arquivos digitais</td><td>Política de guarda</td><td>Restauração testada e exportação</td></tr></table></div>'),
 ('Como a Arquindex estrutura o projeto','<ol><li>Diagnóstico: volume, formatos, estado do acervo, departamentos e frequência de consulta.</li><li>Piloto: amostra representativa para validar captura, metadados e pesquisa.</li><li>Execução: lotes rastreáveis, conferência e correção das exceções.</li><li>Aceite: comparação do inventário com os arquivos e aprovação pelo responsável.</li><li>Operação: suporte, controle de acessos, cópias de segurança e revisão dos prazos.</li></ol>'),
 ('Presença e atendimento regional','<p>A operação da Arquindex está sediada em Belo Horizonte. Projetos na Região Metropolitana de Belo Horizonte e na Região Metropolitana de São Paulo são planejados conforme volume, logística e necessidade de atuação presencial. Serviços de consultoria e implantação podem combinar trabalho remoto e atividades locais previstas em proposta. Esta página não declara unidade física em São Paulo.</p>'),
 ('O que informar ao solicitar um orçamento','<p>Envie estimativa de páginas ou caixas, tipos documentais, local do acervo, quantidade de campos de indexação, prazo desejado e destino dos originais. Para arquivos digitais, informe volume em GB, formatos, usuários, regras de acesso e integrações. Não envie documentos pessoais ou confidenciais pelo contato comercial; solicite primeiro um canal autorizado.</p>')])
add('atendimento/gestao-documental-rm-bh','Digitalização e gestão documental na RM BH | Arquindex','Planeje digitalização, organização de arquivos, ECM e LGPD na Região Metropolitana de Belo Horizonte: escopo, logística e aceite.',
 'Na RM BH, um projeto documental pode começar pelo inventário do acervo e avançar até a consulta digital por departamento. A sede operacional da Arquindex em Belo Horizonte permite planejar a execução a partir da localização dos documentos, da rotina de consultas e das condições de acesso.',[
 ('Planejamento para Belo Horizonte, Contagem, Betim e Nova Lima','<p>O orçamento deve identificar onde cada conjunto está armazenado e quem pode liberá-lo. Em operações com várias unidades, a coleta por lote reduz o risco de misturar acervos. A realização de visitas, coleta e execução no cliente depende de avaliação e contratação; a indicação das cidades não representa filiais.</p>'),
 ('Quando o acervo não pode sair da empresa','<p>Defina espaço de preparação e captura, energia, rede, responsáveis pelo acesso e forma de transferência dos arquivos. Documentos que precisam continuar disponíveis devem seguir uma fila com solicitação e devolução registradas. O piloto mede a capacidade de atendimento antes da definição do cronograma completo.</p>'),
 ('Exemplo de lote de departamento pessoal','<p>Um inventário pode relacionar unidade, matrícula interna, pasta, tipo documental e intervalo de datas. A captura deve manter a associação entre documento e dossiê. A conferência verifica páginas faltantes, legibilidade, duplicidades e permissões. Nomes, CPF e informações médicas não devem ficar expostos em links públicos ou títulos acessíveis a terceiros.</p>'),
 ('Como comparar propostas na RM BH','<ul><li>Confirme se o preço contempla preparação, captura, OCR, indexação e revisão.</li><li>Compare transporte, destinação dos originais e quantidade de campos.</li><li>Exija critérios de aceite e tratamento das falhas.</li><li>Defina responsável pela liberação de cada lote e pelo aceite final.</li></ul>')])
add('atendimento/gestao-documental-rm-sp','Serviços documentais na RM SP: como planejar | Arquindex','Digitalização, Alfresco ECM, LGPD e guarda digital para projetos na Grande São Paulo. Planejamento por unidade, logística e integração.',
 'Na Região Metropolitana de São Paulo, a integração de documentos de várias unidades exige mais do que escanear pastas: é necessário preservar a origem de cada lote, padronizar metadados e entregar uma forma consistente de consulta. A Arquindex estrutura o atendimento conforme o escopo e a logística acordados.',[
 ('Projetos em São Paulo, Guarulhos, Osasco, Barueri e ABC','<p>O desenho do projeto começa com a distribuição do acervo: quais unidades guardam os originais, onde os usuários consultam e quem aprova a entrega. Coletas, deslocamentos e atividades presenciais precisam constar da proposta. A Arquindex tem sede operacional em Belo Horizonte; o atendimento à RM SP não implica a existência de escritório local.</p>'),
 ('Uma biblioteca digital para várias unidades','<p>Padronize tipos documentais e campos obrigatórios antes de migrar. Identifique a unidade produtora e separe documentos por permissões reais de negócio. Em um ECM, o mesmo padrão pode ser aplicado a compras, contratos e engenharia sem permitir que todos os usuários vejam tudo.</p>'),
 ('Transição sem interromper as consultas','<ol><li>Selecione uma unidade piloto com documentos representativos.</li><li>Defina uma janela de movimentação e um inventário de saída e retorno.</li><li>Capture, confira e libere os documentos por lote.</li><li>Teste pesquisa e permissões com usuários de unidades diferentes.</li><li>Expanda apenas após o aceite e o tratamento das exceções.</li></ol>'),
 ('Integração remota e orçamento','<p>Implantação do Alfresco, modelagem de metadados e consultoria LGPD podem combinar reuniões remotas e validação com a equipe do cliente. Para dimensionar o projeto, informe quantidade de unidades, páginas e GB, usuários simultâneos, sistemas existentes, requisitos de disponibilidade e regras de exportação.</p>')])
add('guias/contratar-servicos-digitalizacao-documentos','Como contratar serviços de digitalização de documentos | Arquindex','Checklist de contratação de digitalização: preparação, captura, OCR, indexação, controle de qualidade e aceite por lote.',
 'Um serviço de digitalização deve entregar documentos legíveis, completos e localizáveis. O preço por página só pode ser comparado quando preparação, OCR, metadados, conferência e destinação dos originais estão definidos no mesmo escopo.',[
 ('O que precisa estar na proposta','<ul><li>Unidade de cobrança: página, imagem, documento, pasta ou lote.</li><li>Preparação: retirada de grampos, ordenação e tratamento de exceções.</li><li>Captura: formatos, resolução, cor e documentos de grandes dimensões.</li><li>Pesquisa: OCR e campos usados para localizar cada documento.</li><li>Qualidade: itens conferidos, amostragem, correção e aceite.</li><li>Logística: inventário, transporte, guarda temporária e devolução.</li></ul>'),
 ('OCR e PDF/A cumprem funções diferentes','<p>OCR produz texto pesquisável a partir da imagem e pode falhar com manuscritos, carimbos ou originais pouco legíveis. PDF/A é uma família de formatos voltada à preservação; sua geração precisa ser validada. Nenhum dos dois, isoladamente, comprova autenticidade ou autoriza descarte de originais.</p>'),
 ('Como validar o piloto','<p>Escolha documentos bons e difíceis: frente e verso, páginas claras e escuras, formulários, anexos e tamanhos distintos. Compare a sequência de páginas com o original; teste a busca por campos e texto. Registre como serão corrigidas páginas ausentes, cortes, rotação incorreta e associação ao dossiê errado. Não aprove o lote apenas pela quantidade de arquivos.</p>'),
 ('Digitalização para efeitos legais','<p>Quando o Decreto 10.278/2020 for aplicável, o projeto deve identificar os requisitos técnicos, de assinatura e de metadados pertinentes ao caso. Existem exclusões de escopo e diferenças entre relações com entidades públicas e entre particulares. A eliminação de papel depende da análise do conjunto, das obrigações de preservação e das autorizações necessárias.</p>'),
 ('Quanto custa e quanto demora?','<p>Volume não é o único fator: estado físico, preparação, formatos especiais, campos de indexação e revisão alteram o esforço. A estimativa deve partir do piloto e separar valores recorrentes, implantação, transporte e opções. A Arquindex dimensiona projetos na RM BH e RM SP com base nesses dados, sem presumir uma média fixa de páginas por caixa.</p>')])
add('guias/alfresco-ecm-implantacao-e-automacao','Alfresco ECM: implantação e automação documental | Arquindex','Guia para planejar Alfresco Community: metadados, permissões, regras, conectores, backup e testes antes da implantação.',
 'Alfresco ECM organiza conteúdo e metadados em um repositório com recursos de pesquisa, permissões e versionamento. O resultado depende do modelo documental e da operação. A edição Community deve ser avaliada com a versão, a arquitetura e as integrações pretendidas.',[
 ('O que definir antes de instalar','<p>Liste tipos documentais, responsáveis, campos obrigatórios, níveis de acesso, retenção e volume de arquivos. Separe ambientes de teste e produção. Dimensione banco, armazenamento, índices e serviços de transformação a partir da carga prevista e dos requisitos de recuperação.</p>'),
 ('Metadados, aspectos e regras','<p>Tipos e aspectos modelam informações associadas aos documentos. Regras de pasta podem apoiar ações sobre o conteúdo conforme a configuração da versão. Uma tabela de temporalidade exige também evento de início, fundamento, prazo validado, situação e responsável. Preencher um prazo não significa que a eliminação deva ocorrer automaticamente.</p>'),
 ('Recebimento, aprovação, revisão e compartilhamento','<ol><li>Receber em área de entrada com acesso restrito e identificação de origem.</li><li>Validar formato, associação ao dossiê e campos obrigatórios.</li><li>Encaminhar ao responsável e registrar a decisão.</li><li>Manter versão aprovada e histórico de revisões.</li><li>Compartilhar somente com usuários ou destinatários autorizados.</li></ol><p>Fluxos avançados, OCR, assinatura e integrações com IA podem exigir serviços externos ou desenvolvimento. Não são presumidos como recursos nativos prontos da edição Community.</p>'),
 ('Como integrar IA e automações','<p>Use uma identidade técnica com permissões mínimas, registre as operações e valide a resposta da API. Classificação sugerida por IA deve permitir correção humana. Evite encaminhar dados pessoais a provedores externos sem avaliar finalidade, contrato, segurança e demais requisitos aplicáveis. Automatizações precisam tolerar falhas sem duplicar documentos.</p>'),
 ('Checklist de aceite operacional','<ul><li>Pesquisa encontra documentos e respeita as permissões.</li><li>Versionamento e atualização de metadados foram testados.</li><li>Backup cobre banco, conteúdo e configurações relevantes.</li><li>Restauração foi ensaiada e teve resultado registrado.</li><li>Integrações tratam erro, indisponibilidade e repetição de chamadas.</li><li>Exportação e documentação permitem continuidade da operação.</li></ul>')])
add('guias/consultoria-lgpd-gestao-documental','Consultoria LGPD aplicada à gestão documental | Arquindex','Como ligar diagnóstico LGPD, mapa de dados, ROPA, políticas, acessos e retenção à rotina de documentos da empresa.',
 'A consultoria LGPD aplicada aos documentos começa entendendo como os dados pessoais são recebidos, usados, compartilhados e armazenados. Políticas precisam refletir essa rotina e ter responsáveis, controles e evidências de execução.',[
 ('Diagnóstico por processo','<p>Mapeie contratação, atendimento, compras e demais processos relevantes. Registre categorias de dados e titulares, finalidade, origem, sistemas, compartilhamentos, acesso e retenção. A definição das bases legais deve considerar cada finalidade; consentimento não é uma solução universal.</p>'),
 ('Entregáveis que devem conversar entre si','<div class="table"><table><tr><th>Entrega</th><th>Uso na operação</th></tr><tr><td>Mapa de dados e registros de operações</td><td>Identificar onde os dados circulam e quem responde</td></tr><tr><td>Plano de ação</td><td>Priorizar riscos, responsáveis e evidências</td></tr><tr><td>Políticas e procedimentos</td><td>Orientar acesso, compartilhamento e resposta a incidentes</td></tr><tr><td>Regras de retenção</td><td>Relacionar prazo, evento, fundamento e destinação</td></tr><tr><td>RIPD, quando pertinente</td><td>Avaliar riscos e medidas para o tratamento analisado</td></tr></table></div>'),
 ('Do documento de política ao controle real','<p>Uma política de acesso deve corresponder aos grupos e permissões no sistema. Uma regra de retenção deve identificar qual evento inicia a contagem, como se confirma esse evento e quem autoriza a destinação. Solicitações de titulares exigem identificação adequada, registro e análise do direito aplicável ao caso.</p>'),
 ('Como avaliar uma proposta de consultoria','<ul><li>Quais áreas e sistemas serão analisados?</li><li>O projeto contempla entrevistas e validação com responsáveis?</li><li>Os modelos serão adaptados aos processos?</li><li>Como serão acompanhadas as ações e suas evidências?</li><li>Que atividades continuam após a entrega inicial?</li></ul><p>Certificados ou checklists isolados não demonstram conformidade integral. O atendimento da Arquindex pode combinar consultoria e integração dos controles ao acervo digital.</p>')])
add('guias/gestao-documental-classificacao-temporalidade','Gestão documental: classificação e temporalidade na prática | Arquindex','Como organizar documentos por função, tipo e evento, controlar retenção e registrar decisões de destinação com rastreabilidade.',
 'Gestão documental acompanha o ciclo de vida dos documentos, da produção ou recebimento à destinação. Uma estrutura de pastas ajuda na navegação, mas precisa ser combinada com classificação, responsáveis, acesso e regras de retenção.',[
 ('Comece pela função e pelo tipo documental','<p>Identifique o processo que produz cada documento e sua função. Separe tipo documental de assunto ou nome de arquivo. Use um dicionário de tipos com código, descrição, campos mínimos e responsável por alterações. Isso reduz nomes diferentes para o mesmo documento e facilita a migração entre sistemas.</p>'),
 ('O prazo começa em qual evento?','<p>Um prazo pode depender de encerramento contratual, desligamento ou outra ocorrência definida na regra aplicável. Sem o evento confirmado, o documento não deve receber uma data de eliminação inventada. Registre a situação como aguardando evento ou regra pendente de validação, conforme o caso.</p>'),
 ('Exemplo de registro, sem prazo presumido','<div class="table"><table><tr><th>Campo</th><th>Exemplo de preenchimento</th></tr><tr><td>Tipo</td><td>Contrato de prestação de serviços</td></tr><tr><td>Evento</td><td>Encerramento confirmado</td></tr><tr><td>Data do evento</td><td>Informada por responsável autorizado</td></tr><tr><td>Prazo e fundamento</td><td>Regra validada para o conjunto</td></tr><tr><td>Situação</td><td>Em guarda / em avaliação</td></tr><tr><td>Destinação</td><td>Decisão documentada após verificação</td></tr></table></div>'),
 ('Antes de eliminar','<p>Confira valor permanente, obrigações legais e regulatórias, litígios, auditorias e suspensões de descarte. Gere uma relação dos documentos, obtenha autorização competente e registre a execução. O vencimento de um campo no sistema deve abrir uma avaliação; não substituir a responsabilidade pela decisão.</p>'),
 ('Como implantar por departamento','<p>Comece com um conjunto de alto uso, valide os tipos e faça um piloto. Treine quem recebe e quem consulta. Meça erros de classificação, documentos sem campos obrigatórios, tempo de localização e pendências de avaliação. Expanda quando o padrão estiver estável.</p>')])
add('guias/guarda-digital-documentos-seguranca','Guarda digital de documentos: segurança e recuperação | Arquindex','Checklist para contratar guarda digital: acesso, integridade, backup, restauração, retenção, exportação e continuidade.',
 'Guarda digital é a manutenção controlada de documentos para consulta e preservação ao longo do tempo. O serviço precisa ir além de disponibilizar uma pasta na nuvem: é necessário definir acesso, integridade, recuperação, retenção e saída dos dados.',[
 ('Guarda digital, backup e ECM','<p>Backup permite recuperar dados após perda ou falha. ECM acrescenta organização, metadados e controles de uso. Guarda digital reúne responsabilidades de custódia e disponibilidade previstas no serviço. Um backup sem teste pode falhar na hora necessária; um ECM sem cópia recuperável também permanece exposto a perda.</p>'),
 ('O que exigir do fornecedor','<ul><li>Critérios de acesso, desligamento de usuários e revisão de permissões.</li><li>Proteção na transmissão e no armazenamento, conforme arquitetura.</li><li>Registro das operações relevantes e controle de alterações.</li><li>Frequência de backup e prazo de recuperação contratados.</li><li>Teste de restauração com registro dos resultados.</li><li>Exportação dos arquivos e metadados em formatos utilizáveis.</li><li>Procedimento de encerramento e eliminação conforme o contrato e requisitos aplicáveis.</li></ul>'),
 ('RPO e RTO em linguagem simples','<p>RPO indica a perda de dados tolerada no tempo; RTO, o tempo pretendido para recuperar o serviço. São metas de projeto e contrato, não garantias automáticas do armazenamento em nuvem. Escolha valores compatíveis com o impacto da indisponibilidade e verifique o resultado dos ensaios.</p>'),
 ('Um teste de recuperação verificável','<ol><li>Escolha um lote de teste e registre arquivos, metadados e permissões esperados.</li><li>Restaure em ambiente isolado, sem sobrescrever produção.</li><li>Compare integridade, quantidade, abertura e pesquisa dos documentos.</li><li>Registre tempos, falhas e correções necessárias.</li><li>Atualize o procedimento e repita após mudanças relevantes.</li></ol>'),
 ('Orçamento de guarda digital','<p>Informe volume inicial, crescimento mensal, quantidade de usuários, frequência de consulta e integrações. Compare limites de armazenamento, transferência, implantação, suporte e exportação. Para documentos pessoais ou sigilosos, confirme as responsabilidades das partes e as condições de acesso e compartilhamento.</p>')])
add('blog/do-papel-a-guarda-digital-metodologia-arquindex','Do papel à guarda digital: metodologia Arquindex | Arquindex','Um roteiro prático para unir captura, qualidade, ECM, proteção de dados e preservação em um projeto documental.',
 'Um arquivo escaneado só resolve parte do problema. O ganho operacional aparece quando a equipe consegue encontrar o documento certo, usar a versão aprovada e controlar quem pode acessá-lo. Este roteiro editorial apresenta como conectar as etapas do projeto.',[
 ('1. Inventário antes da captura','<p>Registre o que existe, onde está e quem responde pelo conjunto. Uma caixa pode conter quantidades muito diferentes de páginas e tipos documentais. A medição por amostra evita transformar uma estimativa em compromisso sem validação.</p>'),
 ('2. Qualidade antes do volume','<p>O piloto deve revelar as exceções: documentos frágeis, frente e verso, anexos, formatos especiais e escrita pouco legível. A conferência precisa testar completude e recuperação, além da aparência da imagem. Cada lote deve ter rastreabilidade e responsável pelo aceite.</p>'),
 ('3. Informação estruturada no ECM','<p>Campos mínimos e vocabulários consistentes tornam a pesquisa útil. No Alfresco, o modelo precisa refletir os documentos e suas permissões. Automações devem registrar resultados e encaminhar falhas para tratamento, sem criar uma segunda biblioteca desorganizada.</p>'),
 ('4. Proteção de dados na rotina','<p>O mapa de dados orienta quem acessa, para qual finalidade e por quanto tempo. A configuração deve acompanhar as políticas. Um documento de departamento pessoal não deve ficar público porque foi incluído em uma automação ou link de compartilhamento.</p>'),
 ('5. Preservação demonstrada','<p>Defina cópias de segurança, teste a recuperação e mantenha opções de exportação. A destinação dos originais exige análise própria. Para RM BH e RM SP, o projeto também precisa prever logística, disponibilidade para consultas e responsabilidades por unidade.</p>')])
css='''*{box-sizing:border-box}body{margin:0;color:#142938;background:#f4f7fa;font:18px/1.7 system-ui,sans-serif}a{color:#00647a;text-underline-offset:4px;overflow-wrap:anywhere}header{background:#092c43;color:#fff;padding:24px max(5vw,20px)}header a{color:#fff}nav{display:flex;gap:22px;flex-wrap:wrap}.wrap{max-width:1080px;margin:auto;padding:32px 22px}h1{font-size:clamp(2rem,5vw,3.5rem);line-height:1.12;letter-spacing:-.025em}h2{font-size:1.55rem;line-height:1.3}section{background:#fff;border:1px solid #dbe5ec;border-radius:14px;padding:24px;margin:22px 0}.intro{font-size:1.2rem}.eyebrow{font-size:.8rem;letter-spacing:.14em;text-transform:uppercase;color:#087083}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,260px),1fr));gap:16px}.card{padding:18px;border:1px solid #cadce6;border-radius:12px;background:#fff}.cta{display:inline-block;background:#075e72;color:white;border-radius:8px;padding:12px 20px;margin:10px 0}table{border-collapse:collapse;width:100%;font-size:1rem}td,th{padding:12px;border:1px solid #d3e0e8;text-align:left;vertical-align:top}th{background:#eaf1f6}.table{overflow-x:auto}footer{border-top:1px solid #ccdbe4;font-size:.9rem}li{margin-bottom:8px}.meta{font-size:.9rem;color:#4a626f}a:focus-visible{outline:3px solid #bd5b00;outline-offset:4px}'''
sources=[('Decreto 10.278/2020 — texto oficial','https://www.planalto.gov.br/ccivil_03/_ato2019-2022/2020/decreto/d10278.htm'),('ANPD — materiais educativos e orientações','https://www.gov.br/anpd/pt-br/centrais-de-conteudo/materiais-educativos-e-publicacoes'),('Alfresco — documentação Community','https://docs.alfresco.com/content-services/community/')]
for p in pages:
 related=[q for q in pages if q!=p]
 blocks=''.join(f'<section><h2>{html.escape(h)}</h2>{body}</section>' for h,body in p['sections'])
 links=''.join(f'<a class="card" href="{q["url"]}">{html.escape(q["title"].split(" | ")[0])}</a>' for q in related)
 schema={'@context':'https://schema.org','@graph':[{'@type':'Organization','@id':BASE+'#organization','name':'Arquindex Gestão Documental LTDA','url':BASE,'telephone':'+55-31-97363-2725'}, {'@type':'Article' if '/guias/' in p['url'] or '/blog/' in p['url'] else 'WebPage','@id':p['url']+'#page','url':p['url'],'name':p['title'].split(' | ')[0],'headline':p['title'].split(' | ')[0],'description':p['description'],'inLanguage':'pt-BR','publisher':{'@id':BASE+'#organization'},'author':{'@id':BASE+'#organization'}}]}
